// CF-00 · "Summarize Error (no PII)" — only metadata is kept; node input data (résumés,
// passwords, tokens) is never copied into the audit log or the alert e-mail.
const e = $input.first().json;
const exec = e.execution || {};
const wf = e.workflow || {};
const err = exec.error || (e.trigger && e.trigger.error) || {};
const scrub = s => String(s || '')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[EMAIL]')
  .replace(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[JWT]')
  .replace(/(password|secret|api[_-]?key|token)["'\s:=]+[^\s"',}]+/gi, '$1=[REDACTED]')
  .slice(0, 600);
const name = wf.name || 'unknown workflow';
return [{ json: {
  workflow_id: wf.id || null,
  workflow_name: name,
  execution_id: exec.id ? String(exec.id) : null,
  execution_url: exec.url || null,
  failed_node: exec.lastNodeExecuted || (err.node && err.node.name) || null,
  error_message: scrub(err.message || err.description || 'Unknown error'),
  mode: exec.mode || null,
  at: new Date().toISOString(),
  severity: /CF-0[1357]/.test(name) ? 'HIGH' : 'MEDIUM',
} }];
